SET DEFINE OFF

-- ----------------------------------------------------------------------------------------- Ausbaustufe
MERGE INTO GR_SCHEMA t USING (SELECT 1 AS VERSION FROM DUAL) q ON (t.VERSION = q.VERSION)
WHEN NOT MATCHED THEN INSERT (VERSION, APP_VERSION, TEXT) VALUES (1, 'Phase 17', 'Datenbank: 36 Tabellen, Fälle mit Wegen, Straße, Ort, Fahrplan, Klima, Chronik der Stunden, Tage, Fahrten und Busse, Merkpunkte, Sitzung');

