WHEN MATCHED THEN UPDATE SET t.ART = 'NEBEN', t.TEILE = 42, t.PUNKTE = 2183, t.LAENGE_KM = 230.01 WHERE t.HERKUNFT = 'MITGELIEFERT'
WHEN NOT MATCHED THEN INSERT (HOEHE_M, ART, TEILE, PUNKTE, LAENGE_KM, HERKUNFT)
