MERGE INTO GR_FALL t USING (SELECT 'Sieben Schwestern' AS NAME FROM DUAL) q ON (t.NAME = q.NAME)
WHEN MATCHED THEN UPDATE SET t.ART = 'HAUPT', t.KANTE = MDSYS.SDO_GEOMETRY(2001, 8307, MDSYS.SDO_POINT_TYPE(7.0942545, 62.10764894, NULL), NULL, NULL), t.X_M = -5785.1, t.Y_M = 408.1, t.Z_M = -874.5, t.FUSS_E = 400610, t.FUSS_N = 6887550, t.RICHTUNG_GRAD = 125.4, t.HOEHE_M = 410, t.BREITE_M = 90, t.STRAEHNEN = 7, t.JUNI_M3S = 2.5, t.UEBERHANG = 1, t.NUR_REGEN = 0, t.FALLHOEHE_M = 275.3, t.FALLZEIT_S = 34.77, t.FREI_MAX_M = 90.7, t.FELS_ANTEIL = 0.85, t.BEFUND = 'BELEGT', t.QUELLE_ID = (SELECT MAX(ID) FROM GR_QUELLE WHERE KURZ = 'WP_SCHWESTERN'), t.BEMERKUNG = 'Wege auf dem Gelände ohne die Feinform der Wand (die Szene rechnet sie mit cliff)' WHERE t.HERKUNFT = 'MITGELIEFERT'
WHEN NOT MATCHED THEN INSERT (NAME, ART, KANTE, X_M, Y_M, Z_M, FUSS_E, FUSS_N, RICHTUNG_GRAD, HOEHE_M, BREITE_M, STRAEHNEN, JUNI_M3S, UEBERHANG, NUR_REGEN, FALLHOEHE_M, FALLZEIT_S, FREI_MAX_M, FELS_ANTEIL, BEFUND, QUELLE_ID, BEMERKUNG, HERKUNFT)
