-- ------------------------------------------------------------------------ Presets der Packages (F34 A)
MERGE INTO GR_PAKET_PRESET t USING (SELECT 'com.dan.ocean' AS PAKET, 'Ocean' AS KLASSE, 'Fjord (Szene, Bft 2)' AS NAME FROM DUAL) q ON (t.PAKET = q.PAKET AND t.KLASSE = q.KLASSE AND t.NAME = q.NAME)
WHEN MATCHED THEN UPDATE SET t.BESCHREIBUNG = 'Stand der Szene Geiranger' WHERE t.HERKUNFT = 'MITGELIEFERT'
WHEN NOT MATCHED THEN INSERT (PAKET, KLASSE, NAME, BESCHREIBUNG, HERKUNFT)
  VALUES ('com.dan.ocean', 'Ocean', 'Fjord (Szene, Bft 2)', 'Stand der Szene Geiranger', 'MITGELIEFERT');
DELETE FROM GR_PAKET_WERT WHERE PAKET_PRESET_ID IN (SELECT ID FROM GR_PAKET_PRESET WHERE PAKET = 'com.dan.ocean' AND KLASSE = 'Ocean' AND NAME = 'Fjord (Szene, Bft 2)' AND HERKUNFT = 'MITGELIEFERT');
